const original=new Map();document.querySelectorAll('[data-i18n]').forEach(el=>original.set(el,el.innerHTML));
let places=[],districts=[],events=[],state=freshState(),currentView='journey',mode='districts',checkFilter='all',pageLimit=24,watchId=null,activeRoute=null,lastReply='',chatSite=null,db=null,dbError=null,zoom=1,urls=[],persistError=false;
const enDivision={'ঢাকা':'Dhaka','চট্টগ্রাম':'Chattogram','খুলনা':'Khulna','রাজশাহী':'Rajshahi','বরিশাল':'Barishal','সিলেট':'Sylhet','রংপুর':'Rangpur','ময়মনসিংহ':'Mymensingh','ময়মনসিংহ':'Mymensingh'};
