const lang=()=>state.language==='bn';const tr=(en,b)=>lang()?b:en;const nameOf=p=>lang()?p.name:(p.en||p.name);const districtName=f=>lang()?f.properties.bn:(englishDistrict[f.properties.shapeName]||f.properties.shapeName);const districtOf=p=>districts.find(d=>districtKey(d.properties.bn)===districtKey(p.district));
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),4500);}
function persist(){state.lastSaved=new Date().toISOString();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));persistError=false;}catch{persistError=true;toast(tr('Storage is full or blocked. Changes are in memory only; export a backup.','স্টোরেজ পূর্ণ বা বন্ধ। পরিবর্তন শুধু মেমরিতে আছে; ব্যাকআপ নিন।'));}document.querySelector('.local-indicator').title=persistError?'Not saved':'Local storage only';document.querySelector('.local-indicator span:last-child').textContent=persistError?'Not saved — export backup':tr('Saved on this device','এই ডিভাইসে সংরক্ষিত');}
function setLanguage(){document.documentElement.lang=state.language;for(const [el,html] of original)el.innerHTML=lang()?(bn[el.dataset.i18n]||html):html;$('language').value=state.language;$('chatLanguage').value=lang()?'bn-BD':'en-US';hydrateIcons();render();}
function setView(view){if(!$( 'view-'+view))return;currentView=view;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!=='view-'+view);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const label=document.querySelector(`#nav [data-view="${view}"] span`);$('crumb').textContent=label?.textContent||tr('Privacy & settings','গোপনীয়তা ও সেটিংস');if(view==='journal'){renderJournal();renderRoutes();}if(view==='places')renderPlaces();if(view==='settings')$('settingsName').value=state.name;if(view==='buddies')renderBuddies();window.scrollTo({top:0,behavior:'instant'});}
function render(){
 const s=stats(state,places,districts);$('profileName').textContent=state.name||tr('Explorer','অভিযাত্রী');$('avatar').textContent=(state.name||'E').slice(0,1).toUpperCase();
 const cards=[['temple',tr('Heritage places visited','দেখা ঐতিহ্যস্থান'),`${s.sites} <small>/ ${s.total.toLocaleString()}</small>`,tr(`${s.remaining.toLocaleString()} places left to discover`,`${s.remaining.toLocaleString()}টি স্থান দেখা বাকি`)],['map',tr('Districts explored','দেখা জেলা'),`${s.districts} <small>/ 64</small>`,tr(`${s.districtRemaining} districts still waiting`,`${s.districtRemaining}টি জেলা দেখা বাকি`)],['compass',tr('Heritage explored','ঐতিহ্য অনুসন্ধান'),`${s.percent}<small>%</small>`,tr(`${(100-s.percent).toFixed(1)}% yet to explore`,`${(100-s.percent).toFixed(1)}% এখনও বাকি`)],['award',tr('Your explorer badge','আপনার অর্জন'),esc(s.badge),tr('Every little journey counts','প্রতিটি ভ্রমণই মূল্যবান')]];
 $('stats').innerHTML=cards.map((c,i)=>`<div class="stat-card"><div class="stat-icon">${icon(c[0])}</div><div><div class="stat-label">${c[1]}</div><div class="stat-number ${i===3?'badge-number':''}">${c[2]}</div><small class="stat-note">${c[3]}</small>${i===2?`<div class="stat-progress"><span style="width:${s.percent}%"></span></div>`:''}</div></div>`).join('');
 $('miniStat').textContent=`${s.districts} / 64`;$('miniBadge').textContent='✧ '+s.badge;renderMap();renderChecklist();renderFeatured();renderPlaces();renderFestivals();
 $('miniMap').innerHTML=`<svg viewBox="0 0 700 620" aria-hidden="true">${districts.map(f=>`<path d="${f._path}" fill="${visitedDistricts(state,places,districts).has(f.properties.shapeName)?'#719563':'#d9e3c9'}" stroke="#fcfdf6" stroke-width="2"/>`).join('')}</svg>`;
}
function renderMap(){
 const visited=visitedDistricts(state,places,districts);let html='<g id="mapLayer">';
 html+=districts.map(f=>`<path class="district-path ${visited.has(f.properties.shapeName)?'is-visited':''}" d="${f._path}" data-district="${esc(f.properties.shapeName)}" tabindex="${mode==='districts'?'0':'-1'}" role="button" aria-label="${esc(districtName(f))}" aria-pressed="${visited.has(f.properties.shapeName)}"><title>${esc(districtName(f))}</title></path>`).join('');
 const precise=places.filter(p=>p.coords&&!p.approx&&p.coords[0]>20&&p.coords[0]<27&&p.coords[1]>88&&p.coords[1]<93);
 html+=precise.map(p=>{const [x,y]=mapProject(p.coords[1],p.coords[0]);return `<circle class="site-marker ${state.visited.includes(p.id)?'is-visited':''}" cx="${x}" cy="${y}" r="${mode==='sites'?5:3}" data-place="${esc(p.id)}" tabindex="${mode==='sites'?0:-1}" role="button" aria-label="${esc(nameOf(p))}"><title>${esc(nameOf(p))}</title></circle>`;}).join('');
 for(const r of state.routes){if(r.points.length>1)html+=`<path class="route-line" d="${r.points.map((p,i)=>(i?'L':'M')+mapProject(p.lng,p.lat).join(',')).join('')}"/>`;}
 html+='</g>';$('travelMap').innerHTML=html;$('travelMap').setAttribute('viewBox',`${350-350/zoom} ${310-310/zoom} ${700/zoom} ${620/zoom}`);
 document.querySelector('.map-surface').classList.toggle('sites-mode',mode==='sites');$('mapInstruction').textContent=mode==='districts'?tr('Tap a district to mark it visited','জেলা ছুঁয়ে ভ্রমণ চিহ্নিত করুন'):tr(`${precise.length} non-approximate pins · tap for details`,`${precise.length}টি অনানুমানিক পিন · বিস্তারিত দেখুন`);
 document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));
}
function toggleDistrict(id){
 const linked=places.filter(p=>state.visited.includes(p.id)&&districtOf(p)?.properties.shapeName===id);
 if(visitedDistricts(state,places,districts).has(id)){
 if(linked.length&&!confirm(tr(`This district includes ${linked.length} visited heritage places. Remove those visits too? Journal entries are kept.`,`এই জেলায় ${linked.length}টি ঐতিহ্যস্থান দেখা হয়েছে। সেগুলোর চিহ্নও মুছবেন? জার্নাল থাকবে।`))){renderChecklist();return;}
 state.districts=state.districts.filter(d=>d!==id);const ids=new Set(linked.map(p=>p.id));state.visited=state.visited.filter(p=>!ids.has(p));
 }else state.districts.push(id);
 persist();render();
}
function togglePlace(id){if(!places.some(p=>p.id===id))return;const yes=state.visited.includes(id);state.visited=yes?state.visited.filter(p=>p!==id):[...state.visited,id];persist();render();toast(yes?tr('Visit removed. Your journal is unchanged.','ভিজিট মুছে গেছে। জার্নাল অপরিবর্তিত।'):tr('One more memory on your map.','আপনার মানচিত্রে আরও একটি স্মৃতি।'));}
function renderChecklist(){
 const query=normalize($('checklistSearch').value),allVisited=visitedDistricts(state,places,districts);$('checklistTitle').textContent=mode==='districts'?tr('District checklist','জেলা চেকলিস্ট'):tr('Heritage checklist','ঐতিহ্যস্থান চেকলিস্ট');$('checklistSubtitle').textContent=tr('Little checkmarks. Big memories.','ছোট্ট চিহ্নে বড় স্মৃতি।');$('checklistSearch').placeholder=mode==='districts'?tr('Find a district…','জেলা খুঁজুন…'):tr('Find a heritage place…','ঐতিহ্যস্থান খুঁজুন…');
 const openGroups=[...$('checklist').querySelectorAll('details[open]')].map(d=>d.dataset.group);
 let groups=new Map(),rows=0;
 if(mode==='districts'){
 const order=['ঢাকা','চট্টগ্রাম','খুলনা','রাজশাহী','বরিশাল','সিলেট','রংপুর','ময়মনসিংহ'];
 for(const div of order){const group=districts.filter(f=>normalize(f.properties.division)===normalize(div)).sort((a,b)=>districtName(a).localeCompare(districtName(b)));const filtered=group.filter(f=>(!query||normalize(f.properties.bn+' '+f.properties.shapeName+' '+districtName(f)).includes(query))&&(checkFilter==='all'||(checkFilter==='visited')===allVisited.has(f.properties.shapeName)));if(filtered.length)groups.set(div,{rows:filtered,all:group});}
 for(const [key,g] of groups){rows+=g.rows.length;g.html=g.rows.map(f=>`<div class="check-row"><input type="checkbox" id="check-${esc(f.properties.shapeName.replace(/[^\w]/g,''))}" data-check-district="${esc(f.properties.shapeName)}" ${allVisited.has(f.properties.shapeName)?'checked':''}><label for="check-${esc(f.properties.shapeName.replace(/[^\w]/g,''))}">${esc(districtName(f))}</label></div>`).join('');g.title=lang()?key:enDivision[key]||key;g.visited=g.all.filter(f=>allVisited.has(f.properties.shapeName)).length;}
 }else{
 let matches=places.filter(p=>(!query||normalize([p.name,p.en,p.id,p.district,districtOf(p)?.properties.shapeName].join(' ')).includes(query))&&(checkFilter==='all'||(checkFilter==='visited')===state.visited.includes(p.id)));
 const totalMatches=matches.length;matches=matches.slice(0,120);
 for(const p of matches){const key=p.district||'অন্যান্য';if(!groups.has(key))groups.set(key,{rows:[],all:places.filter(p=>p.district===key)});groups.get(key).rows.push(p);}
 for(const [key,g] of groups){rows+=g.rows.length;g.html=g.rows.map(p=>`<div class="check-row"><input type="checkbox" id="site-${esc(p.id)}" data-check-site="${esc(p.id)}" ${state.visited.includes(p.id)?'checked':''}><label for="site-${esc(p.id)}">${esc(nameOf(p))}</label><button class="text-button" data-place="${esc(p.id)}" aria-label="Details: ${esc(nameOf(p))}">↗</button></div>`).join('');g.title=lang()?key:districtName(districtOf(g.rows[0])||{properties:{shapeName:key}});g.visited=g.all.filter(p=>state.visited.includes(p.id)).length;}
 $('checklistCount').textContent=tr(`Showing ${rows} of ${totalMatches} matches`,`${totalMatches}টির মধ্যে ${rows}টি দেখানো হচ্ছে`);
 }
 $('checklist').innerHTML=groups.size?[...groups.entries()].map(([k,g],i)=>`<details class="division" data-group="${esc(k)}" ${query||checkFilter!=='all'||openGroups.includes(k)||(!openGroups.length&&i===0)?'open':''}><summary>${esc(g.title)}<span>${g.visited} / ${g.all.length}</span></summary>${g.html}</details>`).join(''):`<p class="loading">${tr('No matches. Try another search.','কোনো ফল নেই। অন্যভাবে খুঁজুন।')}</p>`;
 if(mode==='districts')$('checklistCount').textContent=tr(`${allVisited.size} of 64 districts explored`,`${allVisited.size} / ৬৪ জেলা দেখা হয়েছে`);
 document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===checkFilter));
}
function renderPlaces(){
 const q=normalize($('placeSearch').value),d=$('placeDistrict').value,status=$('placeStatus').value;
 const list=places.filter(p=>(!q||normalize([p.name,p.en,p.id,p.district,districtOf(p)?.properties.shapeName,p.summary].join(' ')).includes(q))&&(!d||districtKey(p.district)===districtKey(d))&&(status==='all'||(status==='visited')===state.visited.includes(p.id)));
 $('placeCount').textContent=tr(`${list.length.toLocaleString()} directory records · ${Math.min(pageLimit,list.length)} shown`,`${list.length.toLocaleString()}টি রেকর্ড · ${Math.min(pageLimit,list.length)}টি দেখানো হচ্ছে`);
 $('placesGrid').innerHTML=list.slice(0,pageLimit).map(p=>`<article class="place-card"><div class="place-meta">${icon('pin')} ${esc(p.district)} · ${esc(p.category)}</div><h3>${esc(nameOf(p))}</h3>${!lang()&&p.en?`<p>${esc(p.name)}</p>`:''}<span class="tag">${p.approx?tr('Approximate location — confirm locally','আনুমানিক অবস্থান — যাচাই করুন'):p.coords?tr('Source-listed pin · check access','উৎসযুক্ত পিন · প্রবেশাধিকার যাচাই করুন'):tr('No mapped coordinates','কোঅর্ডিনেট নেই')}</span><p>${esc(p.summary)}</p><div class="card-bottom"><button class="text-button" data-place="${esc(p.id)}">${tr('Read the story ↗','বিস্তারিত দেখুন ↗')}</button><button class="visit-button ${state.visited.includes(p.id)?'visited':''}" data-visit="${esc(p.id)}">${state.visited.includes(p.id)?tr('✓ Visited','✓ দেখেছি'):tr('+ Mark visited','+ দেখেছি')}</button></div></article>`).join('')||`<div class="empty-state">${tr('No places match your filters.','কোনো স্থান পাওয়া যায়নি।')}</div>`;
 $('loadMore').hidden=list.length<=pageLimit;
}
function renderFeatured(){const featured=[places.find(p=>p.en==='Somapura Mahavihara'),places.find(p=>p.id==='golden'),places.find(p=>p.id==='dharmarajika')].filter(Boolean);const labels=[tr('ANCIENT WONDERS','প্রাচীন বিস্ময়'),tr('LIVING HERITAGE','জীবন্ত ঐতিহ্য'),tr('A CITY SANCTUARY','নগরের আশ্রয়')];$('featured').innerHTML=featured.map((p,i)=>`<article class="featured-card"><div class="featured-art" style="${i===1?'background:linear-gradient(140deg,#e7debf,#829376)':i===2?'background:linear-gradient(135deg,#d6decc,#a8bca0)':''}">${i===0?'<img src="assets/tracker/journey-hero.jpg" alt="AI illustration inspired by Paharpur" loading="lazy">':`<svg viewBox="0 0 300 150" width="100%" height="100%" aria-hidden="true"><circle cx="220" cy="34" r="22" fill="#f6ebc9" opacity=".6"/><path d="M0 130 Q60 85 130 115T300 110V150H0" fill="#65795b" opacity=".4"/><g stroke="#8a7e4c" fill="#c4ae6d" stroke-width="2"><path d="M110 130h90v-13h-8V86l-42-17-42 17v31h2z"/><path d="M105 86h90L150 48zM122 57h56l-28-27zM150 30V16"/><path d="M140 130v-27q10-15 20 0v27" fill="#6e7051"/></g></svg>`}<span class="art-type">${labels[i]}</span></div><div class="featured-body"><small>${esc(p.district)} · ${i===0?'AI illustration':'Illustration'}</small><h3>${esc(nameOf(p))}</h3><p>${i===0?tr('A quiet encounter with ancient Bengal.','প্রাচীন বাংলার সঙ্গে এক শান্ত পরিচয়।'):i===1?tr('Golden spires among the green hills.','সবুজ পাহাড়ে সোনালি চূড়া।'):tr('A space for reflection in the heart of Dhaka.','ঢাকার বুকে শান্তি ও সাধনার স্থান।')}</p><div class="featured-actions"><button class="text-button" data-place="${esc(p.id)}">${tr('Discover this place ↗','বিস্তারিত দেখুন ↗')}</button><button class="visit-button ${state.visited.includes(p.id)?'visited':''}" data-visit="${esc(p.id)}">${state.visited.includes(p.id)?'✓ '+tr('Visited','দেখেছি'):'+ '+tr('Add visit','দেখেছি')}</button></div></div></article>`).join('');}
function renderFestivals(){$('festivalList').innerHTML=events.map(e=>`<article class="place-card"><div class="place-meta">${icon('calendar')} ${esc(e.tradition)}</div><h3>${esc(lang()?e.festival_name:e.festival_name_en||e.festival_name)}</h3><span class="tag">${esc(e.lunar_date)}</span><p style="display:block">${esc(lang()?e.description_bn:e.description_en)}</p><small>${tr('Date to be confirmed by the local Sangha.','সঠিক তারিখ স্থানীয় সংঘের কাছে নিশ্চিত করুন।')}</small><div class="card-bottom"><a href="calendar.html" class="text-button">${tr('Explore calendar ↗','পঞ্জিকা দেখুন ↗')}</a></div></article>`).join('');}
function showModal(content){$('modalContent').innerHTML=content;if(!$('modal').open)$('modal').showModal();hydrateIcons($('modal'));}
function closeModal(){$('modal').close();}
function showPlace(id){const p=places.find(p=>p.id===id);if(!p)return;chatSite=p.id;const source=safeURL(p.source),search='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.name+' '+p.district+' Bangladesh');showModal(`<div class="modal-detail"><p class="eyebrow">${esc(p.district)} · ${esc(p.category)}</p><h2 class="modal-title">${esc(nameOf(p))}</h2>${p.en?`<p>${esc(p.name)}</p>`:''}<span class="tag">${esc(p.verify||'Directory listing')}</span><p>${esc(p.history||p.summary)}</p><div class="info-box">${p.approx?tr('This pin is approximate, not a verified entrance. Search by name and confirm with the monastery before travelling.','পিনটি আনুমানিক, যাচাইকৃত প্রবেশপথ নয়। নাম ধরে খুঁজুন এবং বিহারের সঙ্গে কথা বলে নিশ্চিত হোন।'):tr('A source-listed location does not guarantee current access. Confirm entry rules and opening times.','উৎসযুক্ত অবস্থান বর্তমান প্রবেশাধিকার নিশ্চিত করে না। সময়সূচি ও নিয়ম জেনে নিন।')}</div><p>${esc(p.trip||'')}</p>${source?`<a class="source-link" href="${esc(source)}" target="_blank" rel="noopener noreferrer">${esc(p.sourceLabel||'Read original source')} ↗</a>`:''}<div class="detail-links"><a class="button white" href="${search}" target="_blank" rel="noopener noreferrer">Google Maps search ↗</a>${p.coords&&!p.approx?`<a class="button white" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=${p.coords.join(',')}">Street View (if available) ↗</a>`:''}<button class="button primary" data-action="detailVisit" data-id="${esc(p.id)}">${state.visited.includes(p.id)?tr('✓ Visited · remove','✓ দেখা হয়েছে · মুছুন'):tr('Mark as visited','দেখেছি হিসেবে রাখুন')}</button><button class="button white" data-action="journalPlace" data-id="${esc(p.id)}">${tr('Write a memory','স্মৃতি লিখুন')}</button><button class="text-button" data-action="askPlace" data-id="${esc(p.id)}">Ask SanghaMitra ↗</button></div></div>`);}
function profileDialog(){showModal(`<h2 class="modal-title">${tr('Make this journey yours.','ভ্রমণ হোক আপনার নিজের।')}</h2><p class="modal-sub">${tr('No account needed. Your name stays on this device unless you choose to share a card.','অ্যাকাউন্ট লাগবে না। শেয়ার না করলে নাম শুধু এই ডিভাইসে থাকে।')}</p><form id="profileForm"><label class="field">${tr('Your explorer name','আপনার নাম')}<input id="profileInput" maxlength="40" value="${esc(state.name)}" placeholder="${tr('Enter your name','আপনার নাম লিখুন')}"></label><button class="button primary">${tr('Save & start exploring','সংরক্ষণ করে শুরু করুন')} ↗</button></form>`);setTimeout(()=>$('profileInput')?.focus(),40);}
function openSignIn(){showModal(`<h2 class="modal-title">Cloud & assistant connections</h2><p class="modal-sub">Not connected in this local edition · এই সংস্করণে সংযুক্ত নয়</p><div class="info-box">Your local profile is not an authenticated cloud account. No token is created and no private map is sent to an assistant.</div><h3 style="margin-top:22px">For the site owner</h3><p>Deploy the included optional SanghaMitra API for online answers. The optional MCP server provides public place lookup; private-map tools require separately issued, scoped, revocable server tokens and an imported map snapshot.</p><p>Cloud sign-in, sync, live buddies and public trip hosting need an authenticated backend. Follow <code>docs/tracker-deployment.md</code> before enabling them. Never paste provider secrets into this website.</p><button class="button primary" data-action="closeModal">Continue privately</button>`);}
function drawCard(canvas,snap){const ctx=canvas.getContext('2d');canvas.width=1200;canvas.height=900;ctx.fillStyle='#f4f5eb';ctx.fillRect(0,0,1200,900);ctx.strokeStyle='#d9dfca';ctx.lineWidth=2;ctx.strokeRect(30,30,1140,840);ctx.fillStyle='#38583d';ctx.font='38px Georgia';ctx.fillText('☸ charjavumi',75,99);ctx.font='13px sans-serif';ctx.fillStyle='#8e9d78';ctx.fillText('TRACK YOUR JOURNEY ACROSS BANGLADESH',77,134);ctx.fillStyle='#365139';ctx.font='36px Georgia';ctx.fillText((snap.name||'Explorer').slice(0,40),75,238,600);ctx.font='21px sans-serif';ctx.fillStyle='#8e9a7e';ctx.fillText('A little further. A little more discovered.',77,282);ctx.font='94px Georgia';ctx.fillStyle='#54734a';ctx.fillText(String(snap.sites),75,425);ctx.font='22px sans-serif';ctx.fillStyle='#8a9878';ctx.fillText(`of ${snap.total.toLocaleString()} heritage places visited`,78,470);const percent=snap.total?Math.round(snap.sites/snap.total*1000)/10:0;ctx.fillStyle='#dfe6d3';ctx.fillRect(78,510,430,8);ctx.fillStyle='#7f9b68';ctx.fillRect(78,510,430*percent/100,8);ctx.font='18px sans-serif';ctx.fillText(`${percent}% explored  ·  ${snap.districts.length} of 64 districts`,78,554);ctx.fillStyle='#e6ead8';ctx.fillRect(78,598,430,58);ctx.font='21px Georgia';ctx.fillStyle='#79864e';ctx.fillText('✧ '+snap.badge,98,635);ctx.save();ctx.translate(540,140);ctx.scale(.92,.92);for(const f of districts){ctx.fillStyle=snap.districts.includes(f.properties.shapeName)?'#7e9e68':'#dce5c9';const p=new Path2D(f._path);ctx.fill(p);ctx.strokeStyle='#f4f5eb';ctx.lineWidth=1.5;ctx.stroke(p);}ctx.restore();ctx.strokeStyle='#dbe1cf';ctx.beginPath();ctx.moveTo(75,748);ctx.lineTo(1125,748);ctx.stroke();ctx.fillStyle='#8c987c';ctx.font='16px sans-serif';ctx.fillText('Created with charjavumi · Self-reported progress, shared by choice.',75,790);ctx.font='14px sans-serif';ctx.fillText(CANONICAL_URL.replace('https://',''),75,824);ctx.font='10px sans-serif';ctx.fillText('Boundaries: geoBoundaries / BBS / OCHA · CC BY 3.0 IGO',75,848);}
let sharedSnapshot=null;
function shareDialog(snapshot=null){sharedSnapshot=snapshot;const snap=snapshot||shareSnapshot(state,places,districts);showModal(`<h2 class="modal-title">${snapshot?tr('A journey worth celebrating.','উদযাপনের মতো একটি যাত্রা।'):tr('Your journey. Your little keepsake.','আপনার ভ্রমণের ছোট্ট স্মারক।')}</h2><p class="modal-sub">${tr('A shareable card, not a public journal. No GPS routes, photos or companions included.','শুধু অগ্রগতির কার্ড। GPS রুট, ছবি বা সঙ্গীর নাম থাকবে না।')}</p>${snapshot?'<div class="info-box">Shared, self-reported snapshot. Viewing this card does not change your own map.</div>':'<label class="share-checkbox"><input type="checkbox" id="includeName" checked> Include my display name / আমার নাম যুক্ত করুন</label>'}<canvas id="shareCanvas" class="share-preview" aria-label="Downloadable travel progress card"></canvas><div class="share-actions"><button class="button primary" data-action="downloadPNG">${icon('download')} Download PNG</button><button class="button white" data-action="downloadJPG">Download JPG</button><button class="button white" data-action="shareCard">${icon('share')} Share card</button><button class="button white" data-action="shareLink">Copy progress link</button></div><p class="share-warning">Download the card and upload it to Facebook, Instagram, WhatsApp, Telegram or TikTok with the website link. Anyone holding a copied progress link can see that snapshot; it cannot be revoked. It contains your district list and aggregate counts, not your exact route. These are district/site counts, not land-area coverage.</p>`);drawCard($('shareCanvas'),snap);}
function currentSnapshot(){return sharedSnapshot||shareSnapshot(state,places,districts,$('includeName')?.checked!==false);}
function downloadBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function clipboard(text){try{await navigator.clipboard.writeText(text);toast(tr('Copied to clipboard.','কপি করা হয়েছে।'));}catch{showModal(`<h2 class="modal-title">Copy your link</h2><textarea class="field" style="width:100%;height:130px" readonly>${esc(text)}</textarea><p>Select and copy the link above.</p>`);}}
function canvasBlob(type='image/png'){return new Promise((resolve,reject)=>$('shareCanvas').toBlob(b=>b?resolve(b):reject(Error('Image export failed')),type,.94));}
async function shareCard(){const blob=await canvasBlob(),file=new File([blob],'charjavumi-journey.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'My Charjavumi journey',text:CANONICAL_URL});}catch(e){if(e.name!=='AbortError')toast('Sharing failed. Download the card instead.');}}else{downloadBlob(blob,'charjavumi-journey.png');toast('Card downloaded. Upload it to your social app with the website link.');}}
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('charjavumi.journal.v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('entries',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function entriesOp(method,arg){if(!db)throw Error(dbError||'Journal storage is unavailable. Please allow browser storage.');return new Promise((resolve,reject)=>{const tx=db.transaction('entries',method==='getAll'?'readonly':'readwrite');const req=tx.objectStore('entries')[method](arg);let value;req.onsuccess=()=>{value=req.result;};tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Storage transaction aborted'));});}
async function renderJournal(){urls.forEach(URL.revokeObjectURL);urls=[];let list;try{list=await entriesOp('getAll');}catch(e){$('journalList').innerHTML=`<div class="info-box">${esc(e.message)}</div>`;return;}list.sort((a,b)=>b.date.localeCompare(a.date));$('journalList').innerHTML=list.length?list.map(e=>`<article class="journal-card"><span class="entry-date">${esc(e.date)} · ${esc(places.find(p=>p.id===e.place)?.name||tr('A moment along the way','পথের একটি মুহূর্ত'))} · ${tr('Private','ব্যক্তিগত')}</span><h3>${esc(e.title)}</h3><p>${esc(e.body)}</p>${e.buddies?.length?`<small>${tr('With','সঙ্গে')}: ${esc(e.buddies.map(id=>state.buddies.find(b=>b.id===id)?.name).filter(Boolean).join(', '))}</small>`:''}<div class="journal-media">${(e.media||[]).map(m=>{const url=URL.createObjectURL(m.blob);urls.push(url);return m.type.startsWith('video/')?`<video controls preload="metadata" src="${url}" aria-label="${esc(m.name)}"></video>`:`<img src="${url}" alt="${esc(m.name)}" loading="lazy">`;}).join('')}</div><div class="card-bottom"><button class="text-button" data-edit-entry="${esc(e.id)}">Edit entry</button><button class="text-button" data-delete-entry="${esc(e.id)}">Delete entry</button></div></article>`).join(''):`<div class="empty-state">${icon('book')}<h3>${tr('The first page is yours.','প্রথম পাতাটি আপনার।')}</h3><p>${tr('Write down a memory, add a photo, and let your travel story grow.','একটি স্মৃতি লিখুন, ছবি যোগ করুন, ভ্রমণের গল্প বেড়ে উঠুক।')}</p><button class="button primary" data-action="newEntry">${tr('Write my first entry','প্রথম স্মৃতি লিখুন')}</button></div>`;}
let editEntry=null;
async function entryDialog(id=null,place=''){try{const all=id?await entriesOp('getAll'):[];editEntry=id?all.find(e=>e.id===id):null;const e=editEntry||{title:'',body:'',date:new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10),place,buddies:[]};showModal(`<h2 class="modal-title">${tr('Keep a little memory.','একটু স্মৃতি রেখে দিন।')}</h2><p class="modal-sub">Private, saved on this device · ${editEntry?'Editing existing entry':'New journal entry'}</p><form id="entryForm"><div class="entry-grid"><label class="field">Date<input id="entryDate" type="date" value="${esc(e.date)}" required></label><label class="field">Place (optional)<select id="entryPlace"><option value="">A moment along the way</option>${places.map(p=>`<option value="${esc(p.id)}" ${e.place===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div><label class="field">Title<input id="entryTitle" value="${esc(e.title)}" maxlength="120" required placeholder="A morning at the vihara…"></label><label class="field">Your story<textarea id="entryBody" maxlength="10000" required placeholder="What would you like to remember?">${esc(e.body)}</textarea></label><label class="field">Photos & videos<input id="entryMedia" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" multiple></label><p class="file-note">Up to 6 files, 20 MB each, 60 MB per entry. Media stays in your browser. No upload, no public gallery.</p>${editEntry?.media?.length?`<label class="share-checkbox"><input type="checkbox" id="removeMedia"> Remove ${editEntry.media.length} existing attachment(s)</label>`:''}<p id="selectedFiles" class="selected-media"></p>${state.buddies.length?`<label class="field">Companions</label><div class="button-row">${state.buddies.map(b=>`<label class="share-checkbox"><input type="checkbox" name="entryBuddy" value="${esc(b.id)}" ${(e.buddies||[]).includes(b.id)?'checked':''}>${esc(b.name)}</label>`).join('')}</div>`:''}<p class="file-note">Adding a journal entry does not automatically mark a place visited.</p><button class="button primary" type="submit">Save memory</button></form>`);}catch(e){toast(e.message);}}
async function saveEntry(form){const button=form.querySelector('[type="submit"]');button.disabled=true;try{const files=[...$('entryMedia').files];const allowed=['image/jpeg','image/png','image/webp','video/mp4','video/webm'];if(files.some(f=>!allowed.includes(f.type)||f.size>20*1024*1024))throw Error('Use JPEG, PNG, WebP, MP4 or WebM files under 20 MB each.');let media=($('removeMedia')?.checked?[]:editEntry?.media||[]);if(media.length+files.length>6)throw Error('Please keep at most 6 attachments per entry.');media=[...media,...files.map(f=>({name:f.name,type:f.type,blob:f}))];if(media.reduce((n,m)=>n+m.blob.size,0)>60*1024*1024)throw Error('Total attachments must be under 60 MB per entry.');const title=$('entryTitle').value.trim(),body=$('entryBody').value.trim();if(!title||!body)throw Error('Please write a title and a memory.');await entriesOp('put',{id:editEntry?.id||crypto.randomUUID(),title,body,date:$('entryDate').value,place:$('entryPlace').value,buddies:[...form.querySelectorAll('[name="entryBuddy"]:checked')].map(x=>x.value),media});closeModal();setView('journal');toast('Memory saved privately on this device.');}catch(e){toast(e.message);}finally{button.disabled=false;}}
function renderBuddies(){$('buddyList').innerHTML=state.buddies.length?state.buddies.map(b=>`<div class="buddy-item"><span class="avatar">${esc(b.name.slice(0,1))}</span><b>${esc(b.name)}</b><button class="text-button" data-remove-buddy="${esc(b.id)}">Remove</button></div>`).join(''):'<p class="muted" style="padding-top:20px">Your next adventure can be a shared memory. Add a companion above.</p>';}
function renderRoutes(){$('routesList').innerHTML=state.routes.map(r=>`<div class="route-item"><span>${esc(new Date(r.started).toLocaleString())} · ${r.points.length} points · ${routeDistance(r.points).toFixed(2)} km ${r.id===activeRoute?'· Recording':''}</span><button class="text-button" data-delete-route="${esc(r.id)}">Delete route</button></div>`).reverse().join('');}
function stopGPS(message='Tracking stopped. Your route remains private.'){if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;const r=state.routes.find(r=>r.id===activeRoute);if(r)r.ended=new Date().toISOString();activeRoute=null;$('trackingDot').classList.remove('on');$('gpsButton').textContent='Start GPS tracking';$('trackingStatus').textContent=message;persist();renderRoutes();renderMap();}
function gpsConsent(){if(watchId!==null){stopGPS();return;}showModal(`<h2 class="modal-title">Record your route, privately.</h2><p>GPS points stay in this browser. No location is sent to a server. Acceptable points automatically add the district you pass through; this can include transit, not just sightseeing. You can remove those districts later.</p><p>Approximate temple pins are never used for automatic check-ins. For reliable nearby pins, you can choose to confirm a visit.</p><div class="info-box">Use HTTPS, grant location permission, and keep this page open. Tracking may pause when your screen locks, the tab is backgrounded or the browser sleeps. This is not a native background tracker or a navigation tool.</div><div class="button-row" style="margin-top:20px"><button class="button primary" data-action="startGPS">I agree · Start recording</button><button class="button white" data-action="closeModal">Not now</button></div>`);}
const nearbyPrompted=new Set();
function startGPS(){closeModal();setView('journal');if(!navigator.geolocation||!window.isSecureContext){toast('GPS requires a secure HTTPS browser with location support.');return;}if(watchId!==null)return;activeRoute=crypto.randomUUID();state.routes.push({id:activeRoute,started:new Date().toISOString(),ended:null,points:[]});$('trackingDot').classList.add('on');$('gpsButton').textContent='Stop GPS tracking';$('trackingStatus').textContent='Waiting for location permission and a reliable GPS fix…';persist();watchId=navigator.geolocation.watchPosition(position=>{const r=state.routes.find(r=>r.id===activeRoute);if(!r)return;const p={lat:position.coords.latitude,lng:position.coords.longitude,accuracy:position.coords.accuracy,time:position.timestamp};if(p.accuracy>80){$('trackingStatus').textContent=`Waiting for a better GPS fix (current accuracy ±${Math.round(p.accuracy)} m).`;return;}if(!acceptPoint(r.points,p))return;if(state.routes.reduce((n,r)=>n+r.points.length,0)>=50000){stopGPS('Recording limit reached. Export and clear older routes to continue.');return;}r.points.push(p);const d=districts.find(f=>inGeometry(p.lng,p.lat,f.geometry));if(d&&!state.districts.includes(d.properties.shapeName))state.districts.push(d.properties.shapeName);persist();render();renderRoutes();$('trackingStatus').textContent=`Recording · ${r.points.length} points · ${routeDistance(r.points).toFixed(2)} km · accuracy ±${Math.round(p.accuracy)} m${d?' · '+districtName(d):' · outside mapped Bangladesh districts'}`;const near=places.find(s=>!s.approx&&s.coords&&!state.visited.includes(s.id)&&!nearbyPrompted.has(s.id)&&haversine(p,{lat:s.coords[0],lng:s.coords[1]})<.1);if(near){nearbyPrompted.add(near.id);toast(`Nearby: ${nameOf(near)}. Open Heritage places to confirm a visit.`);}},error=>{if(error.code===1)stopGPS('Location permission was denied. You can still mark visits manually.');else $('trackingStatus').textContent='GPS temporarily unavailable. Recording is waiting for a reliable fix; stop anytime.';},{enableHighAccuracy:true,maximumAge:0,timeout:25000});renderRoutes();}
async function exportBackup(){toast('Preparing private backup…');try{const entries=await entriesOp('getAll');const out=[];for(const e of entries){const media=[];for(const m of e.media||[])media.push({name:m.name,type:m.type,data:await blobDataURL(m.blob)});out.push({...e,media});}downloadBlob(new Blob([JSON.stringify({format:'charjavumi-backup',version:1,exportedAt:new Date().toISOString(),state,entries:out})],{type:'application/json'}),'charjavumi-private-backup.json');toast('Private backup downloaded. Keep it safe.');}catch(e){toast('Backup failed: '+e.message);}}
function blobDataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Cannot read media'));r.readAsDataURL(blob);});}
async function restoreBackup(file){if(!file)return;try{if(watchId!==null)throw Error('Stop GPS recording before restoring a backup.');if(file.size>100*1024*1024)throw Error('Backup is too large (maximum 100 MB).');const raw=JSON.parse(await file.text());if(raw.format!=='charjavumi-backup'||raw.version!==1||!Array.isArray(raw.entries)||raw.entries.length>2000)throw Error('Invalid or unsupported backup.');const next=validateState(raw.state,new Set(places.map(p=>p.id)),new Set(districts.map(f=>f.properties.shapeName)));let total=0;const entries=[];for(const e of raw.entries){if(!e||typeof e.id!=='string'||typeof e.title!=='string'||typeof e.body!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(e.date)||!Array.isArray(e.media)||e.media.length>6)throw Error('Invalid journal entry.');const media=[];for(const m of e.media){if(!['image/jpeg','image/png','image/webp','video/mp4','video/webm'].includes(m.type)||typeof m.data!=='string'||!m.data.startsWith(`data:${m.type};base64,`))throw Error('Invalid media in backup.');const bytes=Uint8Array.from(atob(m.data.split(',')[1]),c=>c.charCodeAt(0));total+=bytes.length;if(bytes.length>20*1024*1024||total>75*1024*1024)throw Error('Backup media exceeds safe import limits.');media.push({name:String(m.name).slice(0,200),type:m.type,blob:new Blob([bytes],{type:m.type})});}entries.push({id:e.id.slice(0,100),title:e.title.slice(0,120),body:e.body.slice(0,10000),date:e.date,place:places.some(p=>p.id===e.place)?e.place:'',buddies:Array.isArray(e.buddies)?e.buddies.filter(id=>next.buddies.some(b=>b.id===id)):[],media});}if(!confirm('Replace this device’s tracker visits, routes, journal and media with this backup? Export your current data first.'))return;const old=state;const oldJSON=JSON.stringify(old);try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));}catch{throw Error('Not enough local storage. Your current journal was not changed.');}try{await replaceEntries(entries);}catch(e){localStorage.setItem(STORAGE_KEY,oldJSON);throw e;}state=next;persist();setLanguage();renderJournal();renderBuddies();renderRoutes();$('settingsName').value=state.name;toast('Backup restored.');}catch(e){toast('Restore failed: '+e.message);}finally{$('restoreFile').value='';}}
function replaceEntries(entries){if(!db)return Promise.reject(Error('Journal storage unavailable'));return new Promise((resolve,reject)=>{const tx=db.transaction('entries','readwrite'),store=tx.objectStore('entries');store.clear();entries.forEach(e=>store.put(e));tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error||Error('Restore transaction aborted'));tx.onerror=()=>reject(tx.error);});}
function assistantOpen(){ $('assistantPanel').hidden=false;setTimeout(()=>$('chatInput').focus(),30);}
function message(text,role='bot',links=[]){const div=document.createElement('div');div.className='message '+role;div.textContent=text;for(const link of links){const url=safeURL(link.url);if(url){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='\n'+link.title+' ↗';div.append(a);}}$('chatMessages').append(div);$('chatMessages').scrollTop=$('chatMessages').scrollHeight;if(role==='bot')lastReply=text;return div;}
function findPlaces(q){const term=normalize(q);const direct=places.filter(p=>normalize(p.name+' '+p.en+' '+p.id+' '+p.district).includes(term));if(direct.length)return direct;const tokens=term.replace(/[?.!,“”]/g,'').split(' ').filter(t=>t.length>=4&&!['tell','about','which','have','just','from','mark','visited','please','buddhist','temple','place','places','returned'].includes(t));return places.map(p=>({p,score:tokens.reduce((n,t)=>n+(normalize(p.name+' '+p.en+' '+p.id+' '+p.district).includes(t)?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).map(x=>x.p);}
async function chat(q){message(q,'user');$('chatInput').value='';const b=$('chatLanguage').value.startsWith('bn');const n=normalize(q);const bang=(en,bn)=>b?bn:en;
 if($('onlineAI').checked){const endpoint=window.CHARJAVUMI_CHAT_ENDPOINT||'/api/chat';const selected=findPlaces(q)[0]||places.find(p=>p.id===chatSite);const pending=message(bang('Looking up the configured online assistant…','অনলাইন সহায়কের উত্তর খোঁজা হচ্ছে…'));try{const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),45000);let response;try{response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,language:b?'bn':'en',site_id:selected?.id||null}),signal:controller.signal});}finally{clearTimeout(timeout);}if(!response.ok)throw Error('Online AI is not configured or is unavailable.');const data=await response.json();if(typeof data.answer!=='string')throw Error('Invalid AI response');pending.remove();message(data.answer,'bot',data.sources||[]);return;}catch{pending.remove();message(bang('Online AI is unavailable. No generated answer was returned. Turn off online AI to use the source-based local guide.','অনলাইন AI অনুপলব্ধ। স্থানীয় গাইড ব্যবহার করতে অনলাইন AI বন্ধ করুন।'));return;}}
 if(/progress|stats|how many|remaining|অগ্রগতি|কত.*দেখ|বাকি/.test(n)){if(!$('allowStats').checked){message(bang('Please enable “Allow local guide to read my visit stats” above. Your map is private until you grant access.','উপরে ভ্রমণ-পরিসংখ্যান পড়ার অনুমতি দিন। অনুমতি ছাড়া আপনার ম্যাপ পড়ব না।'));return;}const s=stats(state,places,districts);const left=places.filter(p=>!state.visited.includes(p.id)).slice(0,5);message(bang(`You have visited ${s.sites} of ${s.total} heritage records (${s.percent}%) and ${s.districts} of 64 districts. ${s.remaining} places remain. A few still waiting: ${left.map(nameOf).join('; ')}. Your recorded route distance is ${s.distance.toFixed(2)} km. Counts are self-reported; district transit may be GPS-added.`,`আপনি ${s.total}টির মধ্যে ${s.sites}টি ঐতিহ্যস্থান (${s.percent}%) এবং ৬৪টির মধ্যে ${s.districts}টি জেলা দেখেছেন। বাকি ${s.remaining}টি স্থান। রেকর্ড করা দূরত্ব ${s.distance.toFixed(2)} কিমি।`));return;}
 if(/mark|unmark|চিহ্নিত|দেখেছি|ভিজিট/.test(n)){const matches=findPlaces(q).slice(0,5);message(bang('I never change your map silently. Choose the exact place below, then use its Mark visited button. District mentions are not enough to mark every temple visited.','আপনার অনুমতি ছাড়া ম্যাপ বদলাই না। নিচে নির্দিষ্ট স্থান বেছে “দেখেছি” বোতাম চাপুন। জেলার নাম বললেই সব মন্দির দেখা হয়েছে ধরা হয় না।'));appendPlaceButtons(matches);return;}
 if(/maps|মানচিত্র|ম্যাপ/.test(n)){message(bang('Available map: Bangladesh Buddhist heritage, with 64 district boundaries and the source-linked directory. World/Europe maps and cloud sync are not connected.','বাংলাদেশের বৌদ্ধ ঐতিহ্যের মানচিত্রে ৬৪ জেলা ও উৎসযুক্ত স্থান-তালিকা আছে। বিশ্ব/ইউরোপ ম্যাপ ও ক্লাউড সিঙ্ক সংযুক্ত নয়।'));return;}
 const matches=findPlaces(q).slice(0,5);if(matches.length){const p=matches[0];chatSite=p.id;message(`${p.en||p.name}\n${p.name}\n\n${p.history||p.summary}\n\n${bang('Directory content is currently Bengali. Verify opening hours, access and any approximate pin locally.','সময়সূচি, প্রবেশাধিকার ও আনুমানিক পিন স্থানীয়ভাবে যাচাই করুন।')}`,'bot',p.source?[{title:p.sourceLabel||'Original source',url:p.source}]:[]);appendPlaceButtons(matches);}else message(bang('Try a place name such as Dharmarajika, Shalban, Rajban, পাহাড়পুর, or a district. The local guide searches Bengali names and available English aliases; it is not a general multilingual generative assistant.','ধর্মরাজিকা, শালবন, রাজবন বা জেলার নাম দিয়ে খুঁজুন। স্থানীয় গাইড বাংলা নাম ও উপলব্ধ ইংরেজি নাম খোঁজে; এটি সাধারণ জেনারেটিভ AI নয়।'));
}
function appendPlaceButtons(list){if(!list.length)return;const div=document.createElement('div');div.className='chat-prompts';div.style.flexWrap='wrap';div.innerHTML=list.map(p=>`<button data-place="${esc(p.id)}">${esc(nameOf(p))} ↗</button>`).join('');$('chatMessages').append(div);$('chatMessages').scrollTop=$('chatMessages').scrollHeight;}
function loadVoices(){if(!('speechSynthesis' in window))return;const language=$('chatLanguage').value.slice(0,2);const voices=speechSynthesis.getVoices().filter(v=>v.lang.startsWith(language));$('voiceSelect').innerHTML='<option value="">Device default voice</option>'+voices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} · ${esc(v.lang)}</option>`).join('');}
function speak(){if(!('speechSynthesis' in window)){toast('Speech synthesis is not supported in this browser.');return;}if(!lastReply){toast('Ask the guide a question first.');return;}const voice=speechSynthesis.getVoices().find(v=>v.voiceURI===$('voiceSelect').value);const language=$('chatLanguage').value;if(!speechSynthesis.getVoices().some(v=>v.lang.startsWith(language.slice(0,2)))){toast('No matching voice is installed. Add a voice in your device settings.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(lastReply);u.lang=language;if(voice)u.voice=voice;u.rate=.94;u.onerror=()=>toast('Voice playback failed. Try another device voice.');speechSynthesis.speak(u);}
function dictate(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Voice input is not supported here. Please type your question.');return;}if(!confirm('Your browser may send microphone audio to its speech recognition provider. Continue with voice input?'))return;const recognition=new Recognition();recognition.lang=$('chatLanguage').value;recognition.onresult=e=>{$('chatInput').value=e.results[0][0].transcript;$('chatInput').focus();};recognition.onerror=()=>toast('Microphone unavailable or permission denied. Please type instead.');recognition.start();toast('Listening… review the transcript before sending.');}
const actions={
 profile:profileDialog,start:()=>{if(!state.name)profileDialog();else{setView('journey');document.querySelector('.map-layout').scrollIntoView({behavior:'smooth'});}},share:()=>shareDialog(),closeModal,assistant:assistantOpen,closeAssistant:()=>{$('assistantPanel').hidden=true;window.speechSynthesis?.cancel();},signin:openSignIn,zoomIn:()=>{zoom=Math.min(3,zoom+.3);renderMap();},zoomOut:()=>{zoom=Math.max(1,zoom-.3);renderMap();},fitMap:()=>{zoom=1;renderMap();},resetVisits:()=>{if(confirm('Remove all district and heritage visit marks? Your journal and GPS routes will be kept.')){state.visited=[];state.districts=[];persist();render();}},loadMore:()=>{pageLimit+=24;renderPlaces();},detailVisit:el=>{togglePlace(el.dataset.id);showPlace(el.dataset.id);},journalPlace:el=>entryDialog(null,el.dataset.id),askPlace:el=>{closeModal();assistantOpen();chat(places.find(p=>p.id===el.dataset.id)?.en||places.find(p=>p.id===el.dataset.id)?.name||'');},saveProfile:()=>{state.name=$('settingsName').value.trim().slice(0,40);persist();render();toast('Profile saved on this device.');},downloadPNG:async()=>downloadBlob(await canvasBlob(),'charjavumi-journey.png'),downloadJPG:async()=>downloadBlob(await canvasBlob('image/jpeg'),'charjavumi-journey.jpg'),shareCard,shareLink:()=>clipboard(CANONICAL_URL+'#card='+encodeShare(currentSnapshot())),newEntry:()=>entryDialog(),gps:gpsConsent,startGPS,exportRoute:()=>{if(!state.routes.some(r=>r.points.length)){toast('No GPS points recorded yet.');return;}if(confirm('Download your precise GPS location history? Keep the file private.'))downloadBlob(new Blob([JSON.stringify(routeGeoJSON(state.routes))],{type:'application/geo+json'}),'charjavumi-private-routes.geojson');},backup:exportBackup,deleteAll:async()=>{if(!confirm('Permanently delete ALL tracker visits, routes, buddies, journals and media on this browser? This cannot be undone.'))return;if(watchId!==null)stopGPS();try{await replaceEntries([]);localStorage.removeItem(STORAGE_KEY);state=freshState();setLanguage();renderBuddies();renderJournal();renderRoutes();$('settingsName').value='';toast('All tracker data deleted from this browser.');}catch(e){toast('Could not delete all data: '+e.message);}},readAloud:speak,stopVoice:()=>window.speechSynthesis?.cancel(),dictate
};
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action],[data-view],[data-mode],[data-filter],[data-place],[data-visit],[data-district],[data-edit-entry],[data-delete-entry],[data-remove-buddy],[data-delete-route],[data-prompt]');if(!el)return;try{if(el.dataset.action){await actions[el.dataset.action]?.(el);return;}if(el.dataset.view){setView(el.dataset.view);return;}if(el.dataset.mode){mode=el.dataset.mode;checkFilter='all';$('checklistSearch').value='';$('checklist').innerHTML='';renderMap();renderChecklist();return;}if(el.dataset.filter){checkFilter=el.dataset.filter;renderChecklist();return;}if(el.dataset.place){showPlace(el.dataset.place);return;}if(el.dataset.visit){togglePlace(el.dataset.visit);return;}if(el.dataset.district&&mode==='districts'){toggleDistrict(el.dataset.district);return;}if(el.dataset.editEntry){await entryDialog(el.dataset.editEntry);return;}if(el.dataset.deleteEntry){if(confirm('Delete this private journal entry and its attachments?')){await entriesOp('delete',el.dataset.deleteEntry);await renderJournal();}return;}if(el.dataset.removeBuddy){if(confirm('Remove this companion from your local list?')){state.buddies=state.buddies.filter(b=>b.id!==el.dataset.removeBuddy);persist();renderBuddies();}return;}if(el.dataset.deleteRoute){if(confirm('Delete this recorded route? District visit marks will be kept.')){if(el.dataset.deleteRoute===activeRoute)stopGPS();state.routes=state.routes.filter(r=>r.id!==el.dataset.deleteRoute);persist();renderRoutes();renderMap();}return;}if(el.dataset.prompt)await chat(el.dataset.prompt);}catch(e){console.error(e);toast('Could not complete that action: '+e.message);}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.checkDistrict)toggleDistrict(el.dataset.checkDistrict);if(el.dataset.checkSite)togglePlace(el.dataset.checkSite);if(el.id==='language'){state.language=el.value;persist();setLanguage();loadVoices();}if(el.id==='placeDistrict'||el.id==='placeStatus'){pageLimit=24;renderPlaces();}if(el.id==='includeName')drawCard($('shareCanvas'),currentSnapshot());if(el.id==='restoreFile')restoreBackup(el.files[0]);if(el.id==='entryMedia')$('selectedFiles').textContent=[...el.files].map(f=>`${f.name} (${(f.size/1024/1024).toFixed(1)} MB)`).join(', ');if(el.id==='chatLanguage')loadVoices();if(el.id==='onlineAI')$('assistantMode').textContent=el.checked?'Online AI · requires configured server':'Source-based local guide';});
$('checklistSearch').addEventListener('input',renderChecklist);$('placeSearch').addEventListener('input',()=>{pageLimit=24;renderPlaces();});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id==='profileForm'){state.name=$('profileInput').value.trim().slice(0,40);persist();closeModal();render();document.querySelector('.map-layout').scrollIntoView({behavior:'smooth'});}if(form.id==='entryForm')await saveEntry(form);if(form.id==='buddyForm'){const name=$('buddyName').value.trim();if(name&&state.buddies.length<100){state.buddies.push({id:crypto.randomUUID(),name:name.slice(0,60)});persist();renderBuddies();form.reset();}else toast('Enter a name. Maximum 100 companions.');}if(form.id==='chatForm'){const q=$('chatInput').value.trim();if(q)await chat(q);}});
$('travelMap').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-district],[data-place]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
$('travelMap').addEventListener('pointerover',e=>{const el=e.target.closest('[data-district],[data-place]');if(!el)return;$('mapTooltip').textContent=el.querySelector('title')?.textContent||'';$('mapTooltip').style.display='block';});$('travelMap').addEventListener('pointerleave',()=>$('mapTooltip').style.display='none');
$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('pagehide',()=>{if(watchId!==null)stopGPS('Recording ended when this page was closed.');window.speechSynthesis?.cancel();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&watchId!==null)persist();});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY&&watchId===null)toast('Tracker data changed in another tab. Reload this page before editing to avoid overwriting changes.');});
if('speechSynthesis'in window){speechSynthesis.addEventListener('voiceschanged',loadVoices);loadVoices();}
function handleHash(){if(!districts.length)return;const shared=location.hash.match(/^#card=(.+)$/);if(shared){try{shareDialog(decodeShare(shared[1],new Set(districts.map(f=>f.properties.shapeName))));}catch{toast('This progress link is invalid or damaged. Your own map is unchanged.');}}if(location.hash==='#journal')setView('journal');if(location.hash==='#settings')setView('settings');}
window.addEventListener('hashchange',handleHash);
async function boot(){hydrateIcons();$('checklist').innerHTML='<div class="loading">Loading your heritage map…</div>';try{const [data,geo,festival]=await Promise.all(['data/tracker-places.json','data/tracker-districts.geojson','data/events.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('Unable to load '+url);return r.json();}));places=data.places;districts=geo.features;events=festival.events;districts.forEach(f=>{if(f.properties.shapeName==='Munshiganj')f.properties.division='ঢাকা';if(f.properties.shapeName==='Rangamati')f.properties.division='চট্টগ্রাম';f._path=geometryPath(f.geometry);});try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)state=validateState(JSON.parse(raw),new Set(places.map(p=>p.id)),new Set(districts.map(f=>f.properties.shapeName)));}catch{toast('Stored tracker data could not be read. Export or restore a valid backup; a fresh session is shown.');}state.routes.forEach(r=>{if(!r.ended)r.ended=r.points.length?new Date(r.points.at(-1).time).toISOString():r.started;});$('placeDistrict').innerHTML='<option value="">All districts / সব জেলা</option>'+[...new Set(places.map(p=>p.district).filter(Boolean))].sort().map(d=>`<option value="${esc(d)}">${esc(d)}</option>`).join('');try{db=await openDB();}catch(e){dbError='Journal storage is unavailable in this browser. Visits still work if local storage is enabled.';}setLanguage();renderBuddies();renderRoutes();handleHash();}catch(e){$('checklist').innerHTML=`<div class="info-box">${esc(e.message)}. Check your connection and reload. Serve this site over HTTP(S), not file://.</div>`;toast('The heritage directory could not be loaded. Please reload.');}}
boot();
